const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.933, -29.681]);
  const canberra = ee.Geometry.Point([149.1300, -35.2809]);
  const startDate = '2020-01-15';
  const endDate = '2020-01-21';

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  // Check collection size
  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS images in period: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate total rainfall for each location
  const totalRainfall = chirps.sum();

  // Get rainfall values
  const graftonRain = totalRainfall.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: grafton,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const canberraRain = totalRainfall.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: canberra,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Grafton total rainfall: ${graftonRain?.toFixed(2)} mm`);
  console.log(`Canberra total rainfall: ${canberraRain?.toFixed(2)} mm`);

  // 4. Validation & Final Answer
  if (graftonRain === null || canberraRain === null || 
      isNaN(graftonRain) || isNaN(canberraRain)) {
    console.log("<answer>C3</answer>");
  } else if (graftonRain > canberraRain) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
